from pathlib import Path
import json
D=Path(__file__).parent
core=(D/'src/ripple_core_reference.js').read_text()
f=(D/'src/feedback_sweep.js').read_text()
f=f.replace("const fs=require('node:fs');const path=require('node:path');\n",'').replace("const {RippleNeuron,bound}=require('./ripple_core_reference');\n",'').replace("if(require.main===module)sweep();module.exports={methods,profiles,ControlledNeuron,feasibleTheta,analyticFrequency,evaluate,sweep};",'')
rows=json.loads((D/'data/expanded_colony_trials.json').read_text())
rows=[{k:r[k] for k in ['profile','growth','route','graph','feedback','arrivals','completed','pending','workerSeconds','p95Latency','spawns','retirements','logicalHops','learningApplied']} for r in rows]
score=json.loads((D/'data/feedback_scores.json').read_text())
html=r'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Ripple Cybernetic Mycelium v0.3 · Mathematics Lab</title>
<style>
:root{color-scheme:dark;font-family:system-ui,-apple-system,Segoe UI,sans-serif;background:#0b1716;color:#e6f4ed}*{box-sizing:border-box}body{margin:0;background:radial-gradient(ellipse at 20% 0,#17392e 0,transparent 43%),#0b1716}header,main,footer{max-width:1100px;margin:auto;padding:24px}header{padding-top:38px}h1{font-size:clamp(27px,5vw,48px);letter-spacing:-.04em;line-height:1.1;margin:5px 0 14px}h2{font-size:21px;margin:0 0 16px}p{line-height:1.55;color:#b1c7bc}.tag{font-size:12px;letter-spacing:.12em;text-transform:uppercase;color:#8debc3}.intro{max-width:740px}a{color:#81dfb0}main{display:grid;gap:18px}.panel{border:1px solid #335649;border-radius:18px;background:#11231e;padding:22px;min-width:0}.row{display:flex;gap:14px;flex-wrap:wrap;align-items:center}.fields{display:grid;grid-template-columns:repeat(auto-fit,minmax(165px,1fr));gap:12px;margin:12px 0}label{display:flex;flex-direction:column;font-weight:650;gap:6px;font-size:13px;color:#b1dfca}select,input,button{border:1px solid #47715e;background:#173328;border-radius:9px;color:#f2fff8;font-size:15px;padding:10px;min-width:0}button{background:#1d7450;border-color:#31976a;cursor:pointer;font-weight:700}button:hover{background:#278b63}.primary{background:#2d9367}.metrics{display:grid;grid-template-columns:repeat(auto-fit,minmax(130px,1fr));gap:12px;margin:18px 0}.metric{background:#17342a;border:1px solid #33594a;padding:13px;border-radius:12px}.metric strong{font-size:24px;display:block;font-variant-numeric:tabular-nums}.metric small{color:#b8d4c5}.warning{padding:12px;background:#383020;border-left:3px solid #e6b760;border-radius:7px;font-size:13px;color:#f8deb5}.small{font-size:12px;color:#a9c0b6}.chart{display:block;width:100%;height:240px;background:#0d1d19;border-radius:10px}.legend{display:flex;gap:20px;flex-wrap:wrap;color:#c9dacc;font-size:12px;margin:12px 0}.dot{display:inline-block;width:9px;height:9px;border-radius:50%;margin-right:5px;background:#75d7ac}.dot.blue{background:#8cadfa}table{width:100%;border-collapse:collapse;font-size:13px}td,th{text-align:left;padding:10px;border-bottom:1px solid #335346}td:nth-child(n+2),th:nth-child(n+2){font-variant-numeric:tabular-nums}footer{font-size:12px;color:#a9bcb2;padding-bottom:40px}@media(max-width:600px){header,main,footer{padding:17px}.panel{padding:15px}table{font-size:11px}td,th{padding:6px 3px}}
</style></head><body><header><div class="tag">RIPPLE NEURON / CYBERNETIC MYCELIUM / v0.3</div><h1>A colony that learns its limits.</h1><p class="intro">A falsifiable mathematics laboratory: compare the original Ripple Neuron against alternative firing-threshold controllers and inspect measured-in-model colony scheduling experiments. No backend, network, sensor, or intelligence claim.</p></header><main>
<section class="panel"><h2>1 / Live numerical feedback experiment</h2><p>Simulate two independently reset kernels over 150 model seconds. Inputs are synthetic. The blue curve uses the original v0.1 adaptive neuron; green uses the optional analytic hybrid controller.</p>
<div class="fields"><label>Light drive regime <select id="profile"><option value="constant-mid">Steady mid intensity</option><option value="step-up">Sudden stronger light</option><option value="step-down">Sudden weaker light</option><option value="alternate-20s">Alternating every 20 seconds</option><option value="sine">Smooth fluctuating signal</option><option value="fast-switch">Fast 2-second switching</option><option value="dark-interrupt">Dark interruption</option><option value="blue-suppressed">Blue inhibition</option><option value="ramped">Gradual ramp</option></select></label>
<label>Target firing frequency <select id="target"><option value="0.5">0.5 events/model-second</option><option value="1" selected>1.0 event/model-second</option><option value="2">2.0 events/model-second</option></select></label>
<label>Alternative controller <select id="method"><option value="hybrid-fast">Analytic + feedback</option><option value="feedforward-fast">Analytic only</option><option value="hybrid-slow">Slow analytic + feedback</option><option value="rate-PI">Naive PI control (negative control)</option><option value="fixed">Fixed threshold (negative control)</option></select></label></div>
<button id="simulate">Run simulated experiment</button><div class="metrics" id="neuronMetrics"></div><canvas id="plot" class="chart" width="1000" height="260" aria-label="Firing activity by 10-second window"></canvas><div class="legend"><span><i class="dot blue"></i>Original neuron</span><span><i class="dot"></i>Selected candidate</span></div><p id="neuronNote" class="small"></p></section>
<section class="panel"><h2>2 / Choose the colony's task and architecture</h2><p>All 720 records below were generated by executing the colony simulator, not estimated by this UI. Specialists get a hypothetical processing advantage in these trials; the separate sensitivity study shows where that assumption fails.</p>
<div class="fields"><label>Workload <select id="workload"><option value="balanced">Balanced / three task types</option><option value="learning">Learning-heavy</option><option value="product">Product-heavy</option><option value="study">Study-heavy</option><option value="shift">Changing specialties</option><option value="burst">Demand bursts</option></select></label><label>Growth controller <select id="growth"><option value="capacity-specialist">Capacity-aware specialists</option><option value="capacity-general">Capacity-aware generalists</option><option value="v2-heuristic">v0.2-inspired growth heuristic</option><option value="fixed4">Four fixed generalists</option><option value="specialists4">Four fixed mixed specialists</option></select></label><label>Task routing <select id="routing"><option value="affinity">Specialist affinity</option><option value="learned">Online learned cost estimate</option><option value="leastqueue">Shortest estimated workload</option><option value="roundrobin">Round robin</option></select></label><label>Graph <select id="graph"><option value="tree">Branching tree</option><option value="ring">Ring</option><option value="mesh">Full mesh</option></select></label><label>Neuron kernel <select id="fb"><option value="original">Original</option><option value="hybrid-fast">Optional hybrid</option></select></label></div>
<div class="metrics" id="colonyMetrics"></div><p id="colonyNote" class="warning"></p><h2>Best within searched alternatives for selected workload</h2><div class="row"><button id="economy">Select least simulated occupancy</button><button id="speed">Select lowest p95 delay</button></div><div style="overflow-x:auto;margin-top:14px"><table><thead><tr><th>Objective</th><th>Growth</th><th>Route</th><th>Graph</th><th>p95 delay</th><th>Worker-seconds</th></tr></thead><tbody id="best"></tbody></table></div></section>
<section class="panel"><h2>3 / Evidence and limitations</h2><p><strong>Learning:</strong> distributed logistic-regression gradients on synthetic numeric examples. <strong>Product:</strong> checked integer-cents order totals, inventory shortfalls. <strong>Study:</strong> inverse-variance aggregation with independent-variance assumptions and duplicate source IDs. These are real calculations on synthetic input, not verified factual research or model-level cognition.</p><p><strong>Cost warning:</strong> the worker-seconds and pulse rates are simulated. The 720 trials explicitly assume a matched specialist uses 1 spike per part, a generalist 2, and a mismatched specialist 3. The cost of link transfer is modeled as fixed hop delay; no link congestion, real power, or physical neuron has been measured.</p><p><strong>Scientific foundation:</strong> <a href="https://neuronaldynamics.epfl.ch/online/Ch1.S3.html">Integrate-and-fire dynamics</a>, <a href="https://doi.org/10.1145/324133.324234">work stealing</a>, <a href="https://kubernetes.io/docs/reference/kubernetes-api/autoscaling/horizontal-pod-autoscaler-v2/">replica autoscaling</a>, <a href="https://pmc.ncbi.nlm.nih.gov/articles/PMC11995700/">fungal-electrical-signal research limitations</a>.</p></section>
</main><footer>Offline experiment, CC0-1.0 original code · No live GitHub edits · No web calls · You may copy, adapt and re-test.</footer>
<script>
/* START_REFERENCE */
__CORE__
/* END_REFERENCE */
__FEEDBACK__
const ALL_ROWS=__COLONIES__;
function $(s){return document.getElementById(s)}
const format=x=>typeof x==='number'?(Number.isInteger(x)?String(x):x.toFixed(2)):'—';
function trace(method,profile,target){const n=new ControlledNeuron(method,target),a=[];let count=0;
 for(let i=0;i<3000;i++){const t=i*.05,d=profiles[profile](t);count+=n.step(driveToInput(d),.05).count;if((i+1)%200===0){a.push(count/10);count=0;}}return a;}
function draw(a,b){const canvas=$('plot'),ctx=canvas.getContext('2d'),W=canvas.width,H=canvas.height;ctx.clearRect(0,0,W,H);
 const mx=Math.max(2.5,...a,...b)+.5,margin=34;ctx.lineWidth=1;ctx.strokeStyle='#355247';
 for(let y=0;y<=4;y++){const yy=H-margin-(H-2*margin)*y/4;ctx.beginPath();ctx.moveTo(margin,yy);ctx.lineTo(W-12,yy);ctx.stroke();ctx.fillStyle='#a8c9b6';ctx.fillText((mx*y/4).toFixed(1),4,yy+3);}
 const drawSeries=(series,color)=>{ctx.beginPath();ctx.lineWidth=3;ctx.strokeStyle=color;series.forEach((v,i)=>{const x=margin+i*(W-margin-20)/(series.length-1),y=H-margin-v/mx*(H-2*margin);if(!i)ctx.moveTo(x,y);else ctx.lineTo(x,y)});ctx.stroke();};
 drawSeries(a,'#8cadfa');drawSeries(b,'#75d7ac');ctx.fillStyle='#aac6b6';ctx.fillText('10–150 model seconds, non-overlapping 10-second windows',margin,H-7);
}
function neuron(){const target=+$('target').value,profile=$('profile').value,method=$('method').value;
 const a=evaluate('original',profile,target),b=evaluate(method,profile,target);
 $('neuronMetrics').innerHTML=`<div class="metric"><strong>${format(a.mae)}</strong><small>Original MAE</small></div><div class="metric"><strong>${format(b.mae)}</strong><small>Candidate MAE</small></div><div class="metric"><strong>${a.events}</strong><small>Original spikes</small></div><div class="metric"><strong>${b.events}</strong><small>Candidate spikes</small></div>`;
 $('neuronNote').textContent=`Averaged only over ${a.eligibleWindows} ten-second windows where the mean drive has a theoretically feasible threshold; this is an approximate workload criterion. Simulation runs sequentially in JavaScript.`;
 draw(trace('original',profile,target),trace(method,profile,target));}
function optionsToRow(r){$('growth').value=r.growth;$('routing').value=r.route;$('graph').value=r.graph;$('fb').value=r.feedback;colony();}
function colony(){const profile=$('workload').value,growth=$('growth').value,route=$('routing').value,graph=$('graph').value,fb=$('fb').value;
 const r=ALL_ROWS.find(r=>r.profile===profile&&r.growth===growth&&r.route===route&&r.graph===graph&&r.feedback===fb);
 if(!r){$('colonyMetrics').textContent='No matching executed trial';return;}
 $('colonyMetrics').innerHTML=`<div class="metric"><strong>${r.completed}/${r.arrivals}</strong><small>Jobs completed</small></div><div class="metric"><strong>${format(r.p95Latency)}</strong><small>p95 delay / model s</small></div><div class="metric"><strong>${format(r.workerSeconds)}</strong><small>Simulated worker-seconds</small></div><div class="metric"><strong>${r.spawns} / ${r.retirements}</strong><small>Created / retired</small></div>`;
 $('colonyNote').textContent=r.completed!==r.arrivals?`INCOMPLETE: ${r.pending} jobs still pending at t=230 model seconds. Do not rank as successful.`:'All submitted jobs were completed by t=230 model seconds. Performance applies only to the specified synthetic model.';
 const completed=ALL_ROWS.filter(x=>x.profile===profile&&x.completed===x.arrivals);
 const eco=[...completed].sort((a,b)=>a.workerSeconds-b.workerSeconds||a.p95Latency-b.p95Latency)[0],fast=[...completed].sort((a,b)=>a.p95Latency-b.p95Latency||a.workerSeconds-b.workerSeconds)[0];
 $('best').innerHTML=[['Economy',eco],['Fast response',fast]].map(([label,r])=>`<tr><td>${label}</td><td>${r.growth}</td><td>${r.route}</td><td>${r.graph}</td><td>${format(r.p95Latency)}</td><td>${format(r.workerSeconds)}</td></tr>`).join('');
 $('economy').onclick=()=>optionsToRow(eco);$('speed').onclick=()=>optionsToRow(fast);
}
$('simulate').onclick=neuron;for(const id of ['workload','growth','routing','graph','fb'])$(id).onchange=colony;neuron();colony();
</script></body></html>'''
html=html.replace('__CORE__',core).replace('__FEEDBACK__',f).replace('__COLONIES__',json.dumps(rows,separators=(',',':')).replace('</','<\\/'))
(D/'Ripple-Mycelium-Mathematics-Lab-v0.3.html').write_text(html)
print('wrote',len(html),'chars')
